import React, { useEffect, useState } from 'react';
import axios from 'axios';

const fallback = [
  { id: 1, title: 'Ring 0: kernel exploit discussion', posts: [{id:11, author:'neo', body:'Detalles sobre exploit...'}] },
  { id: 2, title: 'Terminal themes & prompts', posts: [{id:21, author:'trinity', body:'Como configurar powerlevel10k'}] },
  { id: 3, title: 'Offtopic: hardware hacks', posts: [{id:31, author:'morpheus', body:'Raspberry Pi cluster ideas'}] },
];

const ContentList = ({ filter, onSelect, selectedId }) => {
  const [content] = useState(fallback);

  const list = filter ? content.filter(c => c.title.toLowerCase().includes(filter.toLowerCase())) : content;

  return (
    <div>
      {list.map(item => (
        <article key={item.id} className={`card ${selectedId === item.id ? 'selected' : ''}`} onClick={() => onSelect && onSelect(item.id)} style={{ cursor: onSelect ? 'pointer' : 'default' }}>
          <h3 className="neon">{item.title}</h3>
          <div className="muted">{item.posts.length} respuestas</div>
        </article>
      ))}
    </div>
  );
};

export default ContentList;
